#include <cstdint>
#include <iostream>
#include <thread>
#include <chrono>

// Buffer size must be a power of 2 for efficient wrap-around
constexpr size_t BUFFER_SIZE = 1024;

// We use a power of 2 minus 1 for the mask operation
constexpr size_t MASK = BUFFER_SIZE - 1;

// Atomic counters for indices
// We use std::atomic<size_t> to ensure atomic operations
std::atomic<size_t> write_idx{0};
std::atomic<size_t> read_idx{0};

